select energy_manager.load_cards($cards$[
{"id":"p3-018","paper":3,"topic":"Transformers","kind":"problem","front":"A 1000 kVA transformer has 1.8 kW no-load loss and 10.5 kW full-load copper loss. It supplies 600 kVA at 0.9 PF for 24 h/day. Find the total loss, the efficiency at this load, the load for maximum efficiency, and the daily energy lost.","back":"Loss = 5.58 kW; efficiency ≈ 98.98%; maximum efficiency at ≈ 414 kVA (41.4% load); daily loss ≈ 134 kWh.","explain":"Part-load transformer losses use the 'NL + x²·FL_Cu' rule. Maximum efficiency occurs where the variable loss equals the fixed loss. Even at 99% efficiency, the losses are worth tracking because they accumulate every hour of the year.","steps":[{"prompt":"Find the load fraction.","answer":"x = 600/1000 = 0.6","explain":"Per-unit loading on kVA."},{"prompt":"Find the copper loss at this load.","answer":"0.6² × 10.5 = 3.78 kW","explain":"Copper loss ∝ (load)²."},{"prompt":"Find the total loss.","answer":"1.8 + 3.78 = 5.58 kW","explain":"Core loss is constant."},{"prompt":"Find the efficiency.","answer":"Output = 600 × 0.9 = 540 kW; η = 540/(540 + 5.58) = 98.98%","explain":"η = output / (output + losses)."},{"prompt":"Find the load for maximum efficiency.","answer":"√(1.8/10.5) = 0.414, i.e. ≈ 414 kVA","explain":"This is where Cu loss = core loss."},{"prompt":"Find the daily energy loss.","answer":"5.58 × 24 = 133.9 kWh/day","explain":"Energy = power × time."}],"flash":false,"source":"BEE 2025 P3 Q7 (extended)","order":3017},
{"id":"p3-019","paper":3,"topic":"Harmonics & power quality","kind":"fact","front":"Which loads generate harmonics? Give examples.","back":"Non-linear loads that draw non-sinusoidal current, such as VFDs and inverters, UPS, rectifiers, SMPS, LED or CFL drivers, arc furnaces and welding sets.","explain":"A VFD or inverter drive is a far larger harmonic source than an LED lamp, transformer or resistance heater (a resistance heater is linear). Harmonic currents are integer multiples of the 50 Hz fundamental (250 Hz is the 5th harmonic, and so on).","flash":false,"source":"BEE 2024 P3 Q21","order":3018},
{"id":"p3-020","paper":3,"topic":"Harmonics & power quality","kind":"fact","front":"What problems do harmonics cause in an electrical system?","back":"Overheating of transformers, cables and motors; overloaded neutrals from triplen harmonics; capacitor failure from resonance; nuisance tripping; meter errors; interference with electronics.","explain":"Harmonics increase RMS current without adding useful power, which raises I²R and eddy losses. Third-order (triplen) harmonics add in the neutral of 3-phase, 4-wire systems instead of cancelling. Capacitor banks can resonate with system inductance at a harmonic frequency.","flash":false,"source":"syllabus","order":3019},
{"id":"p3-021","paper":3,"topic":"Harmonics & power quality","kind":"fact","front":"What is the effect of voltage unbalance between the three phases on an induction motor?","back":"It causes negative-sequence currents that greatly increase current unbalance, losses and winding temperature, reducing efficiency and motor life.","explain":"A small voltage unbalance (a few percent) produces a current unbalance several times larger, because the motor's negative-sequence impedance is low. The extra heating can force derating. Causes include unequal single-phase loads and blown capacitor fuses, so balance single-phase loads across phases.","flash":false,"source":"BEE 2024 P3 Q30 / BEE 2025 P3 Q23","order":3020},
{"id":"p3-022","paper":3,"topic":"Electric motors","kind":"fact","front":"What is the formula for the synchronous speed of an induction motor?","back":"Ns = 120 f / P (rpm), where f = supply frequency and P = number of poles. It is inversely proportional to the number of poles.","explain":"At 50 Hz: 2 pole = 3000 rpm, 4 pole = 1500 rpm, 6 pole = 1000 rpm, 8 pole = 750 rpm. The rotor runs slightly slower than Ns; that difference (slip) is what induces rotor current and torque.","flash":true,"source":"BEE 2025 P3 Q49","order":3021},
{"id":"p3-023","paper":3,"topic":"Electric motors","kind":"fact","front":"A 4-pole, 50 Hz induction motor runs at 1470 rpm. What is its slip?","back":"0.02 (2%).","explain":"Ns = 120 × 50 / 4 = 1500 rpm. Slip = (Ns − N)/Ns = (1500 − 1470)/1500 = 0.02. Slip rises roughly in proportion to load, which is the basis of the slip method of estimating motor loading.","flash":false,"source":"BEE 2025 P3 Q44","order":3022},
{"id":"p3-024","paper":3,"topic":"Electric motors","kind":"fact","front":"List the five loss components of an induction motor.","back":"Stator copper (I²R) loss, rotor copper loss, core (iron) loss, friction and windage loss, and stray load loss.","explain":"Core loss and friction & windage are roughly fixed and independent of load. Stator and rotor copper losses vary with the square of the load current. Stray load losses arise mainly from leakage flux induced by load currents and also rise with load (roughly with the square of load torque, not inversely).","flash":false,"source":"BEE 2025 P3 Q13","order":3023},
{"id":"p3-025","paper":3,"topic":"Electric motors","kind":"fact","front":"How do motor efficiency and power factor change at light load?","back":"Both fall. Efficiency usually stays near its peak from about 50–100% load but drops sharply below about 40–50%. PF falls significantly as load decreases.","explain":"At light load the fixed losses (core, friction) are a larger share of a small output, and the magnetising current (reactive) stays nearly constant while the active current falls. So the statement 'PF improves as load decreases' is false. Larger motors generally have higher full-load efficiency.","flash":false,"source":"BEE 2024 P3 L1","order":3024},
{"id":"p3-026","paper":3,"topic":"Electric motors","kind":"fact","front":"What is the formula for energy savings from replacing a motor with a more efficient one?","back":"kW saved = kW output × (1/η_old − 1/η_new).","explain":"Input = output/η, so the saving is the difference in input power for the same shaft output. Multiply by operating hours for kWh. Use efficiencies at the actual operating load, not nameplate, and check that the new motor's lower slip does not raise the load on centrifugal equipment.","flash":true,"source":"BEE 2025 P3 Q12","order":3025},
{"id":"p3-027","paper":3,"topic":"Electric motors","kind":"fact","front":"How do energy-efficient (IE2/IE3) motors achieve higher efficiency?","back":"By reducing losses: more copper and larger conductors (lower I²R), thinner low-loss electrical steel laminations (lower core loss), smaller and more efficient cooling fans, and optimised design with tight quality control.","explain":"An IE3 motor's gain over IE2 comes mainly from reduced copper and iron losses, not from increased slip (EE motors actually have lower slip). Inrush current is not lower, and the saving is smallest at very light load.","flash":false,"source":"BEE 2025 P3 Q10 / Q25","order":3026},
{"id":"p3-028","paper":3,"topic":"Electric motors","kind":"fact","front":"Why can replacing a standard motor with a high-efficiency motor on a centrifugal pump or fan sometimes give less saving than expected?","back":"EE motors have lower slip, so they run faster. Under the affinity laws, flow rises with speed and power with speed cubed, which eats into the efficiency gain.","explain":"For example, if speed rises from 1460 to 1480 rpm, the pump flow rises about 1.4% and the shaft power about 4%. Compare kWh per unit of output (e.g. kWh per m³ pumped), not just kW, when validating savings.","flash":false,"source":"BEE 2025 P3 L-4","order":3027},
{"id":"p3-029","paper":3,"topic":"Electric motors","kind":"fact","front":"What is the effect of running a lightly loaded delta-connected motor in star connection?","back":"The phase voltage drops by √3, so the motor's capability falls to about one-third. At low load, iron losses fall and PF and efficiency improve.","explain":"This is a low-cost measure for motors that run below about 40% load most of the time. The motor must never see more than its star-mode capability or it will overheat. Automatic star-delta changeover controllers switch modes based on load.","flash":false,"source":"BEE 2024 P3 Q35","order":3028},
{"id":"p3-030","paper":3,"topic":"Electric motors","kind":"fact","front":"What does a soft starter do?","back":"It ramps up the voltage during starting to limit inrush current and mechanical shock. It does not change full-load speed or improve running efficiency.","explain":"Direct-on-line starting draws 6–8 times rated current. A soft starter uses thyristors to raise the voltage gradually, reducing voltage dips and stress on couplings and belts. Some models also provide energy-saving voltage reduction at light load.","flash":false,"source":"BEE 2024 P3 Q37 / BEE 2025 P3 Q24","order":3029},
{"id":"p3-031","paper":3,"topic":"Electric motors","kind":"fact","front":"In a VFD, what happens if the frequency is reduced while the voltage is kept the same?","back":"The motor is over-fluxed: the magnetising current rises, and the motor draws higher current and may overheat.","explain":"Air-gap flux ∝ V/f, so VFDs keep V/f constant (or use vector control) as speed falls. Keeping V constant while lowering f pushes the core into saturation.","flash":false,"source":"BEE 2024 P3 Q36","order":3030},
{"id":"p3-032","paper":3,"topic":"Electric motors","kind":"fact","front":"How does motor operating temperature affect insulation life?","back":"As a rule of thumb, insulation life roughly doubles for every 10°C reduction in operating temperature (and halves for every 10°C rise).","explain":"This is why overloading, voltage unbalance, poor ventilation and frequent starts shorten motor life. EE motors run cooler because they have lower losses, which also extends their life.","flash":true,"source":"BEE 2025 P3 L-4","order":3031},
{"id":"p3-033","paper":3,"topic":"Electric motors","kind":"problem","front":"A 37 kW, 415 V motor has nameplate current 65 A and PF 0.86. In the field it draws 48 A at 412 V and 0.82 PF. Estimate the rated efficiency and the present percentage loading.","back":"Rated input ≈ 40.2 kW, rated efficiency ≈ 92.1%; actual input ≈ 28.1 kW, loading ≈ 70%.","explain":"Nameplate V, I and PF give rated input power; rated output ÷ rated input is the rated efficiency. Comparing measured input with rated input gives the loading by the input-ratio method. Note that current alone is a poor indicator of load because PF also changes with load.","steps":[{"prompt":"Find the rated input power.","answer":"√3 × 415 × 65 × 0.86 / 1000 = 40.18 kW","explain":"P = √3·V·I·PF."},{"prompt":"Find the rated efficiency.","answer":"37 / 40.18 = 92.1%","explain":"η = rated output / rated input."},{"prompt":"Find the actual input power.","answer":"√3 × 412 × 48 × 0.82 / 1000 = 28.09 kW","explain":"Same formula, measured values."},{"prompt":"Find the percentage loading.","answer":"28.09 / 40.18 = 69.9% ≈ 70%","explain":"Input-ratio method."}],"flash":false,"source":"BEE 2024 P3 S4 (similar)","order":3032},
{"id":"p3-034","paper":3,"topic":"Electric motors","kind":"problem","front":"A pump motor delivers 30 kW at the shaft and runs 6000 h/yr. Its present efficiency is 88%; a replacement IE3 motor would run at 93%. At Rs 8/kWh, find the annual energy and cost savings.","back":"≈ 1.83 kW saved; ≈ 11,000 kWh/yr; ≈ Rs 88,000/yr.","explain":"Savings come from lower input power for the same shaft output. The formula kW_out × (1/η_old − 1/η_new) is a frequent one-mark question. In practice, confirm the shaft load stays the same: a lower-slip motor may speed up a centrifugal load.","steps":[{"prompt":"Find the input power with the old motor.","answer":"30 / 0.88 = 34.09 kW","explain":"Input = output/η."},{"prompt":"Find the input power with the new motor.","answer":"30 / 0.93 = 32.26 kW","explain":"Same output, higher η."},{"prompt":"Find the power saving.","answer":"34.09 − 32.26 = 1.83 kW","explain":"Equals 30 × (1/0.88 − 1/0.93)."},{"prompt":"Find the annual energy and cost saving.","answer":"1.83 × 6000 ≈ 11,000 kWh; × Rs 8 ≈ Rs 88,000","explain":"Multiply by hours, then by the tariff."}],"flash":false,"source":"BEE 2025 P3 Q12 (extended)","order":3033},
{"id":"p3-035","paper":3,"topic":"Compressed air","kind":"fact","front":"How do you calculate the Free Air Delivery (FAD) from displacement and volumetric efficiency?","back":"FAD = swept (displacement) volume × volumetric efficiency. For example, 150 CFM × 0.90 = 135 CFM.","explain":"FAD is the actual air delivered, referred to inlet conditions. It is always below displacement because of clearance volume re-expansion, heating of intake air, valve losses and leakage past rings. Worn compressors show falling volumetric efficiency.","flash":false,"source":"BEE 2025 P3 Q19","order":3034},
{"id":"p3-036","paper":3,"topic":"Compressed air","kind":"fact","front":"How is leakage estimated from a load/unload (on-off) test with all users closed?","back":"Leakage = Compressor FAD × T / (T + t), where T = average on-load time and t = average unload time.","explain":"Example: a 500 cfm compressor loading 5 s and unloading 20 s gives 500 × 5/25 = 100 cfm of leakage (20%). Several cycles are averaged. Leakage in well-maintained systems should be below about 5–10% of capacity.","flash":true,"source":"BEE 2024 P3 Q22","order":3035},
{"id":"p3-037","paper":3,"topic":"Compressed air","kind":"fact","front":"What is the effect of intake air temperature on compressor power?","back":"Cooler intake air reduces power. Each 4°C rise in intake temperature increases power consumption by about 1% for the same output.","explain":"Cooler air is denser, so more mass is delivered per stroke or revolution. Drawing intake air from outside or a shaded, ventilated location rather than the hot compressor room is a standard energy-saving measure. Higher intake temperature therefore lowers efficiency.","flash":true,"source":"BEE 2024 P3 Q42","order":3036},
{"id":"p3-038","paper":3,"topic":"Compressed air","kind":"fact","front":"What saving results from reducing compressor discharge pressure?","back":"Roughly 6–10% of compressor power per 1 bar reduction, so generate air at the lowest pressure the users actually need.","explain":"Higher pressure also increases leakage flow from every leak. Separate high-pressure users can be supplied by a small booster instead of running the whole system at high pressure.","flash":true,"source":"BEE 2024 P3 L1","order":3037},
{"id":"p3-039","paper":3,"topic":"Compressed air","kind":"fact","front":"At higher altitude, how does compressor power compare for the same FAD?","back":"It consumes more power.","explain":"At altitude the ambient pressure is lower, so the compression ratio to reach the same gauge pressure is higher. Less mass is drawn per stroke, so more work is needed per unit of free air delivered.","flash":false,"source":"BEE 2025 P3 Q21","order":3038},
{"id":"p3-040","paper":3,"topic":"Compressed air","kind":"fact","front":"What do the intercooler and aftercooler do in a compressed air system?","back":"The intercooler cools air between stages, bringing compression closer to isothermal and reducing work. The aftercooler cools the discharge air so that moisture condenses and can be drained.","explain":"A fouled intercooler raises the second-stage inlet temperature and power. Proper aftercooling with automatic drain traps reduces the load on dryers and prevents water in the distribution lines.","flash":false,"source":"BEE 2025 P3 Q15 / BEE 2024 P3 Q39","order":3039},
{"id":"p3-041","paper":3,"topic":"Compressed air","kind":"fact","front":"How do desiccant dryers work, and which dryer type usually has the lowest operating cost?","back":"Desiccant dryers adsorb moisture on silica gel or activated alumina. Heat-of-compression dryers, which regenerate using the compressor's own hot discharge air, generally have the lowest operating energy.","explain":"Heatless (purge) dryers lose about 15–20% of the dried air for regeneration, so their running cost is high. Refrigerated dryers are economical for moderate dew-point needs. Choose the highest dew point the process can accept.","flash":false,"source":"BEE 2024 P3 Q40 / BEE 2025 P3 Q45","order":3040},
{"id":"p3-042","paper":3,"topic":"Compressed air","kind":"fact","front":"What are the main features of screw, reciprocating and centrifugal compressors?","back":"Screw: continuous, pulsation-free delivery, but poor efficiency at part load (unloaded running), so not ideal for fluctuating demand without VSD. Reciprocating: good part-load efficiency, pulsating flow. Centrifugal: large capacities, capacity controlled efficiently by inlet guide vanes.","explain":"A VSD on a screw compressor eliminates unloaded running and matches output to demand. Typical practice is to run base-load units at full load and give the trim duty to one VSD or reciprocating unit.","flash":false,"source":"BEE 2024 P3 Q26 / Q41 / Q43","order":3041},
{"id":"p3-043","paper":3,"topic":"Compressed air","kind":"fact","front":"List five energy conservation measures for a compressed air system.","back":"Arrest leaks; reduce generation pressure; draw cool intake air; use VSD or proper capacity control and sequencing; eliminate inappropriate uses and artificial demand; recover compression heat; use no-loss auto drain traps; size piping for low pressure drop; maintain intercoolers and filters.","explain":"This list is asked as a 5-mark short question almost every year. Back each item with a reason, for example '1 bar lower pressure saves about 6–10%' or 'every 4°C cooler intake saves about 1%'.","flash":false,"source":"BEE 2024 P3 S2 / BEE 2025 P3 S-3","order":3042},
{"id":"p3-044","paper":3,"topic":"Compressed air","kind":"problem","front":"In a pump-up test, the receiver plus piping volume is 8.4 m³. With the compressor running and all users isolated, pressure rises from 2.0 to 8.0 bar(g) in 3.5 minutes. Atmospheric pressure is 1.013 bar(a). Estimate the FAD. If rated capacity is 16 m³/min, what is the capacity shortfall?","back":"FAD ≈ 14.2 Nm³/min; shortfall ≈ 11% below rated.","explain":"The pump-up test treats compression into the receiver as isothermal: free air delivered = (P2 − P1)/P0 × V ÷ T. If the compressed-air temperature differs from ambient, multiply by (273 + t_ambient)/(273 + t_air). A large shortfall points to worn valves or rings or a fouled intake filter.","steps":[{"prompt":"Find the pressure rise.","answer":"P2 − P1 = 8.0 − 2.0 = 6.0 bar","explain":"Gauge readings can be used directly because only the difference matters."},{"prompt":"Apply the pump-up formula.","answer":"Q = (6.0/1.013) × 8.4 / 3.5","explain":"Q = (P2 − P1)/P0 × V/T, with V in m³ and T in min."},{"prompt":"Calculate the FAD.","answer":"5.923 × 2.4 ≈ 14.2 Nm³/min","explain":"Free air at atmospheric conditions."},{"prompt":"Compare with the rated capacity.","answer":"(16 − 14.2)/16 ≈ 11% shortfall","explain":"Volumetric efficiency has dropped; inspect the compressor."}],"flash":false,"source":"syllabus","order":3043},
{"id":"p3-045","paper":3,"topic":"Compressed air","kind":"problem","front":"With all users closed, a 20 m³/min compressor loads for 12 s and unloads for 36 s on average. Load power is 110 kW. Estimate the leakage, the percentage leakage, and the annual energy lost (8000 h/yr, neglecting unload power).","back":"Leakage = 5 m³/min (25% of capacity); ≈ 27.5 kW wasted; ≈ 2,20,000 kWh/yr.","explain":"With no consumption, the compressor's loaded time only replaces leaked air, so leak flow = FAD × on-time fraction. Treating the leak as an equal share of loaded running gives the wasted power. Unload power, typically 25–35% of load power for screw units, adds further waste.","steps":[{"prompt":"Find the loaded-time fraction.","answer":"T/(T + t) = 12/(12 + 36) = 0.25","explain":"On-time fraction of the cycle."},{"prompt":"Find the leakage flow.","answer":"20 × 0.25 = 5 m³/min","explain":"Leakage = FAD × T/(T + t)."},{"prompt":"Find the percentage leakage.","answer":"5/20 = 25%","explain":"Far above good practice (below about 10%)."},{"prompt":"Find the power and energy wasted.","answer":"110 × 0.25 = 27.5 kW; × 8000 h = 2,20,000 kWh/yr","explain":"The loaded power share serves only the leaks."}],"flash":false,"source":"BEE 2024 P3 Q22 (extended)","order":3044},
{"id":"p3-046","paper":3,"topic":"Refrigeration & HVAC","kind":"fact","front":"How much cooling is 1 ton of refrigeration (TR)?","back":"1 TR = 3024 kcal/h = 3.517 kW = 12,000 Btu/h.","explain":"It is the heat needed to melt 1 short ton of ice in 24 hours. Example: 27,216 kcal/h ÷ 3024 = 9 TR. In chilled-water systems, TR = flow (kg/h) × ΔT (°C) ÷ 3024.","flash":true,"source":"BEE 2025 P3 Q50","order":3045},
{"id":"p3-047","paper":3,"topic":"Refrigeration & HVAC","kind":"fact","front":"How are COP and kW/TR related?","back":"COP = cooling output ÷ power input (same units); kW/TR = 3.517 ÷ COP.","explain":"For example, a chiller providing 100 kW of cooling at COP 4 draws 25 kW. COP 5.86 ≈ 0.6 kW/TR. A lower kW/TR is better. Energy Efficiency Ratio (EER) is often quoted interchangeably with COP in Indian practice (both are dimensionless ratios, though EER can also be in Btu/Wh).","flash":true,"source":"BEE 2024 P3 Q49","order":3046},
{"id":"p3-048","paper":3,"topic":"Refrigeration & HVAC","kind":"fact","front":"What happens to the refrigerant in each component of a vapour compression cycle?","back":"Evaporator: absorbs heat; liquid evaporates at low pressure. Compressor: raises pressure and temperature. Condenser: rejects heat; vapour condenses to liquid. Expansion valve: throttles, dropping pressure and temperature at constant enthalpy.","explain":"Enthalpy changes across the compressor, condenser and evaporator, but expansion is (ideally) isenthalpic. In an ideal system the refrigerant temperature increases only in the compressor. Total heat rejected in the condenser = refrigeration effect + compressor work.","flash":false,"source":"BEE 2024 P3 Q45-46 / BEE 2025 P3 Q14, Q41","order":3047},
{"id":"p3-049","paper":3,"topic":"Refrigeration & HVAC","kind":"fact","front":"In a LiBr–water vapour absorption machine (VAM), which fluid is the refrigerant and which is the absorbent?","back":"Water is the refrigerant; lithium bromide is the absorbent.","explain":"Ammonia–water VAMs use ammonia as refrigerant and water as absorbent. Ammonia is the refrigerant common to both vapour compression and absorption systems. VAMs are driven by heat (steam, hot water, exhaust) with only small pump power, which makes them attractive where waste heat is available.","flash":false,"source":"BEE 2024 P3 Q47 / BEE 2025 P3 Q8","order":3048},
{"id":"p3-050","paper":3,"topic":"Refrigeration & HVAC","kind":"fact","front":"What is the effect of raising the chilled water leaving temperature (or evaporator temperature)?","back":"It raises chiller efficiency (higher COP, lower kW/TR). About 3% compressor power is saved per 1°C rise in evaporator temperature.","explain":"A higher evaporator temperature means higher suction pressure and a lower compression ratio, so less work per TR. Set the chilled water no colder than the process or comfort load needs. Likewise, a lower condensing temperature (cooler, clean condenser water) improves COP.","flash":true,"source":"BEE 2024 P3 Q48 / BEE 2025 P3 Q33","order":3049},
{"id":"p3-051","paper":3,"topic":"Refrigeration & HVAC","kind":"fact","front":"How does scale or fouling in condenser tubes affect a chiller?","back":"It reduces heat transfer, raises condensing temperature and pressure, and increases compressor energy use.","explain":"Fouling adds thermal resistance, so the refrigerant must condense at a higher temperature to reject the same heat. Watch the condenser approach (refrigerant condensing temperature − leaving water temperature). Tube cleaning and good cooling-water treatment restore performance.","flash":false,"source":"BEE 2025 P3 Q26","order":3050},
{"id":"p3-052","paper":3,"topic":"Refrigeration & HVAC","kind":"fact","front":"Which rejects more heat per TR to the cooling tower: a vapour compression chiller or a VAM?","back":"A VAM rejects much more, typically about 1.6–2 times as much, because it rejects both the refrigeration load and the driving heat input (low COP of about 0.7–1.3).","explain":"Vapour compression chiller: heat rejected = 3024 + kW/TR × 860 kcal/h per TR (e.g. 0.6 kW/TR gives 3540 kcal/h per TR). VAM: 3024 + 3024/COP. So VAMs need larger cooling towers and more pumping. That must enter any economic comparison along with the cost of steam versus power.","flash":false,"source":"BEE 2025 P3 S-6 / BEE 2024 P3 L5","order":3051},
{"id":"p3-053","paper":3,"topic":"Refrigeration & HVAC","kind":"fact","front":"If the dew point temperature equals the dry bulb temperature, what is the relative humidity?","back":"100%: the air is saturated.","explain":"At saturation, dry bulb = wet bulb = dew point. The wider the gap between dry bulb and wet bulb, the drier the air and the greater the potential for evaporative cooling.","flash":false,"source":"BEE 2025 P3 Q4","order":3052},
{"id":"p3-054","paper":3,"topic":"Refrigeration & HVAC","kind":"fact","front":"During evaporative cooling (air washer), what happens to dry bulb temperature, humidity ratio and enthalpy?","back":"Dry bulb falls, humidity ratio rises, and enthalpy stays about constant (it follows the wet bulb line).","explain":"Sensible heat in the air is converted to latent heat of the evaporated water, so total heat is essentially unchanged. Evaporative cooling works best in hot, dry climates.","flash":false,"source":"BEE 2025 P3 Q16","order":3053},
{"id":"p3-055","paper":3,"topic":"Refrigeration & HVAC","kind":"fact","front":"What does an air-side economiser do in an HVAC system?","back":"It uses cool outdoor air for 'free cooling' when outdoor conditions are favourable, reducing mechanical refrigeration.","explain":"Dampers increase outdoor air intake when its enthalpy or temperature is below that of return air. Water-side economisers similarly use cooling-tower water to pre-cool chilled water in cold weather.","flash":false,"source":"BEE 2024 P3 Q16","order":3054},
{"id":"p3-056","paper":3,"topic":"Refrigeration & HVAC","kind":"problem","front":"A chiller cools 100 m³/h of water from 12°C to 7°C. Compressor input is 150 kW. Find the cooling load in TR, kW/TR and COP. If the condenser water ΔT is 5°C, what condenser water flow is needed?","back":"≈ 165.3 TR; 0.907 kW/TR; COP ≈ 3.88; condenser water ≈ 125.8 m³/h.","explain":"Chilled-water TR uses m·cp·ΔT. The condenser must reject the refrigeration effect plus the compressor work (kW × 860 kcal/kWh), which is why condenser flow exceeds chilled water flow at the same ΔT. These are the standard steps of a chiller performance assessment.","steps":[{"prompt":"Find the refrigeration effect.","answer":"100,000 kg/h × 1 × (12 − 7) = 5,00,000 kcal/h","explain":"Q = m·cp·ΔT, with cp of water = 1 kcal/kg°C."},{"prompt":"Convert to TR.","answer":"5,00,000 / 3024 = 165.3 TR","explain":"1 TR = 3024 kcal/h."},{"prompt":"Find kW/TR.","answer":"150 / 165.3 = 0.907 kW/TR","explain":"Specific power consumption."},{"prompt":"Find the COP.","answer":"(165.3 × 3.517) / 150 = 581.5/150 ≈ 3.88","explain":"COP = cooling kW / input kW = 3.517/(kW/TR)."},{"prompt":"Find the condenser heat and water flow.","answer":"5,00,000 + 150 × 860 = 6,29,000 kcal/h; flow = 6,29,000/(1000 × 5) ≈ 125.8 m³/h","explain":"Heat rejected = cooling + work."}],"flash":false,"source":"BEE 2025 P3 S-6 (similar)","order":3055},
{"id":"p3-057","paper":3,"topic":"Buildings & ECBC","kind":"fact","front":"What is the Energy Performance Index (EPI) of a building, and what is its unit?","back":"EPI = total annual energy consumption ÷ built-up area, in kWh/m²/year.","explain":"BEE star ratings for buildings use EPI bands; a lower EPI earns more stars. Use the built-up area (not carpet area) unless the rating scheme specifies otherwise. Total consumption includes grid plus DG/captive electricity.","flash":false,"source":"BEE 2024 P3 Q17 / L6","order":3056},
{"id":"p3-058","paper":3,"topic":"Buildings & ECBC","kind":"fact","front":"Which buildings does the ECBC / Energy Conservation Act provision on buildings apply to?","back":"Commercial buildings with a connected load of 100 kW or more (or contract demand of 120 kVA or more).","explain":"ECBC compliance can be shown by the prescriptive approach, the trade-off approach (Envelope Performance Factor, EPF), or the whole-building performance approach using simulation. EPF compares the envelope of the proposed design against a baseline.","flash":false,"source":"BEE 2025 P3 Q6 / Q35","order":3057},
{"id":"p3-059","paper":3,"topic":"Buildings & ECBC","kind":"fact","front":"What does the Solar Heat Gain Coefficient (SHGC) of a window measure?","back":"The fraction of incident solar radiation admitted through the fenestration as heat. For SHGC 0.25 and 600 W/m² incident, gain = 150 W/m².","explain":"A lower SHGC means less solar heat gain and lower cooling load. Visible Light Transmittance (VLT) measures daylight separately. Effective Aperture = VLT × Window-to-Wall Ratio. ECBC defines a skylight as fenestration sloped less than 60° from horizontal.","flash":false,"source":"BEE 2024 P3 Q15 / L6","order":3058}
]$cards$::jsonb);
